/// setCommands replaces all of `clip`'s commands with those in
/// `commands_json`, as ORI's `REPLACE_ANNOTATION_COMMANDS` does. An
/// empty list, `[]`, clears it.
///
/// C: `otio_ext_ori_set_commands`
pub fn setCommands(document: *Document, clip: Node, commands_json: [:0]const u8) Error!void {
    if (!clip.belongsTo(document)) return Error.ForeignObject;
    var out_error: c.Buffer = .{ .data = null, .len = 0 };
    defer c.otio_buffer_free(out_error);
    const status = c.otio_ext_ori_set_commands(document, clip.handle, commands_json.ptr, &out_error);
    if (status != .ok) return support.statusError(status, out_error);
}

/// timestampNow writes the current time in ISO 8601, for a command's
/// `timestamp`, to `out_timestamp`.
///
/// What this hands back was allocated with allocator, and is the
/// caller's to free.
///
/// C: `otio_ext_ori_timestamp_now`
pub fn timestampNow(allocator: Allocator) Error![]u8 {
    var out_timestamp: c.Buffer = undefined;
    var out_error: c.Buffer = .{ .data = null, .len = 0 };
    defer c.otio_buffer_free(out_error);
    const status = c.otio_ext_ori_timestamp_now(&out_timestamp, &out_error);
    if (status != .ok) return support.statusError(status, out_error);
    defer c.otio_buffer_free(out_timestamp);
    return try support.copyBuffer(allocator, out_timestamp);
}
